import { FlaskConical } from 'lucide-react'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { isMockMode } from '@/lib/config'
import { cn } from '@/lib/utils'

/**
 * Marks content generated by the mock service layer (demo data, simulated AI
 * suggestions, simulated runs). Renders nothing in live mode unless `always`.
 */
export function SimulatedBadge({
  label = 'Simulated',
  reason = 'Produced by the in-browser mock API. No backend, warehouse or AI provider was called.',
  always = false,
  className,
}: {
  label?: string
  reason?: string
  always?: boolean
  className?: string
}) {
  if (!isMockMode && !always) return null
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span
          tabIndex={0}
          className={cn(
            'inline-flex h-5 items-center gap-1 rounded-sm border border-dashed border-border-strong px-1.5 text-[11px] font-medium text-muted-foreground',
            className,
          )}
        >
          <FlaskConical className="size-3" aria-hidden />
          {label}
        </span>
      </TooltipTrigger>
      <TooltipContent className="max-w-xs">{reason}</TooltipContent>
    </Tooltip>
  )
}

/** Confidence meter for AI suggestions: 5 segments plus a percentage. */
export function ConfidenceMeter({ value, className }: { value: number; className?: string }) {
  const pct = Math.round(value * 100)
  const level = value >= 0.85 ? 'High' : value >= 0.7 ? 'Medium' : 'Low'
  const filled = Math.max(1, Math.round(value * 5))
  const tone = value >= 0.85 ? 'bg-foreground' : value >= 0.7 ? 'bg-muted-foreground' : 'bg-warning'
  return (
    <span className={cn('inline-flex items-center gap-1.5', className)} aria-label={`${level} confidence, ${pct}%`}>
      <span className="flex gap-0.5" aria-hidden>
        {Array.from({ length: 5 }, (_, i) => (
          <span key={i} className={cn('h-2.5 w-1 rounded-[1px]', i < filled ? tone : 'bg-border')} />
        ))}
      </span>
      <span className="text-xs tabular text-muted-foreground">{pct}%</span>
    </span>
  )
}
